  "literacy.tutorial.title": "ಕಲಾಕೃತಿಗೆ ಸುಸ್ವಾಗತ — ಇದು ಹೇಗೆ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ",
