  "literacy.tutorial.step2Title": "2. ಸ್ವಯಂಚಾಲಿತ AI ಸ್ಟುಡಿಯೋ ಫೋಟೋಗಳು",
  "literacy.tutorial.step2Desc": "ಸಾಮಾನ್ಯ ಮೊಬೈಲ್‌ನಿಂದ ಫೋಟೋ ತೆಗೆಯಿರಿ. AI ಅನಗತ್ಯ ಹಿನ್ನೆಲೆ ತೆಗೆದು ಸುಂದರಗೊಳಿಸುತ್ತದೆ.",
  "literacy.tutorial.step3Title": "3. ನ್ಯಾಯಯುತ ಬೆಲೆ ಸಲಹೆ",
  "literacy.tutorial.step3Desc": "ಕಚ್ಚಾವಸ್ತು ಮತ್ತು ನಿಮ್ಮ ದಿನಗೂಲಿಯನ್ನು ಲೆಕ್ಕಹಾಕಿ ಸರಿಯಾದ ಬೆಲೆ ನಿರ್ಧರಿಸಲಾಗುತ್ತದೆ.",
  "literacy.tutorial.step4Title": "4. ನೇರವಾಗಿ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಹಣ (DBT)",
