  "tips.modal.title": "ಇಂದಿನ ಸಲಹೆ",
  "tips.modal.gotIt": "ಅರ್ಥವಾಯಿತು",
  "tips.priceFloor": "ಯಾವಾಗಲೂ ನಿಮ್ಮ ವೆಚ್ಚದ ಮಿತಿಗಿಂತ ಹೆಚ್ಚಿನ ಬೆಲೆ ಇಡಿ — ಕಚ್ಚಾ ವಸ್ತು, ನಿಮ್ಮ ಸಮಯ ಮತ್ತು ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಶುಲ್ಕ — ಮಂದಗತಿಯ ತಿಂಗಳಲ್ಲೂ ಸಹ.",
  "tips.trackIncome": "ಪ್ರತಿ ಮಾರಾಟವನ್ನು ದಾಖಲಿಸಿ, ಚಿಕ್ಕದಾಗಿದ್ದರೂ ಸಹ. ಸರಳ ಆದಾಯ ದಾಖಲೆ ದುರ್ಬಲ ಋತುವಿಗೆ ಯೋಜನೆ ಮಾಡಲು ಮತ್ತು ಸಾಲಕ್ಕಾಗಿ ಗಳಿಕೆಯನ್ನು ಸಾಬೀತುಪಡಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
  "tips.bulkOrders": "ಬೃಹತ್ ಮತ್ತು ಸಾಂಸ್ಥಿಕ ಆರ್ಡರ್‌ಗಳು ಸ್ಥಿರವಾಗಿ ಮತ್ತು ಮುಂಗಡವಾಗಿ ಪಾವತಿಸುತ್ತವೆ. ಖರೀದಿದಾರರು ನಿಮ್ಮನ್ನು ಕಂಡುಕೊಳ್ಳಲು ನಿಮ್ಮ ಸಾಮರ್ಥ್ಯ ಮತ್ತು ಸಿದ್ಧತೆಯ ಸಮಯವನ್ನು ನವೀಕರಿಸಿ.",
  "tips.photoQuality": "ಸ್ಪಷ್ಟ, ಉತ್ತಮ ಬೆಳಕಿನ ಮತ್ತು ಹಲವು ಕೋನಗಳಿಂದ ತೆಗೆದ ಫೋಟೋಗಳಿರುವ ಪಟ್ಟಿಗಳು ವೇಗವಾಗಿ ಮಾರಾಟವಾಗುತ್ತವೆ. ನೈಸರ್ಗಿಕ ಬೆಳಕು ಫ್ಲ್ಯಾಶ್‌ಗಿಂತ ಉತ್ತಮವಾಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ.",
  "tips.respondFast": "ನೀವು ಒಂದು ದಿನದೊಳಗೆ ಪ್ರಶ್ನೆಗಳಿಗೆ ಉತ್ತರಿಸಿದಾಗ ಖರೀದಿದಾರರು ಆರ್ಡರ್ ಪೂರ್ಣಗೊಳಿಸುವ ಸಾಧ್ಯತೆ ಹೆಚ್ಚು.",
  "tips.saveSavings": "ಪ್ರತಿ ಪಾವತಿಯ ಒಂದು ಸಣ್ಣ ಭಾಗವನ್ನು ಉಳಿತಾಯವಾಗಿ ತೆಗೆದಿಡಿ — 5% ಕೂಡ ಸೇರಿ ಆರ್ಡರ್‌ಗಳ ನಡುವೆ ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ.",
  "tips.giPremium": "GI ಟ್ಯಾಗ್ ಮೂಲದ ಪುರಾವೆಯಾಗಿದ್ದು ಖರೀದಿದಾರರು ಇದನ್ನು ನಂಬುತ್ತಾರೆ. ಪ್ರಮಾಣೀಕೃತ ವಸ್ತುಗಳಿಗೆ ಸಾಮಾನ್ಯವಾಗಿ ಹೆಚ್ಚಿನ ಬೆಲೆ ಇಡಬಹುದು — ನಿಮ್ಮ ವಸ್ತುವಿನ ಬೆಲೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಬೇಡಿ.",
  "tips.restockEarly": "ಕಚ್ಚಾ ವಸ್ತು ಮುಗಿಯುವ ಮೊದಲೇ ಮರುಪೂರೈಕೆ ಪ್ರಾರಂಭಿಸಿ, ವಿಶೇಷವಾಗಿ ಬೇಡಿಕೆ ಹೆಚ್ಚಾಗುವ ಹಬ್ಬ ಮತ್ತು ಮದುವೆಯ ಋತುಗಳ ಮೊದಲು.",
  "tips.clusterSupport": "ನಿಮ್ಮ ಕ್ಲಸ್ಟರ್ ಸಂಯೋಜಕರು ಬೃಹತ್ ವಸ್ತು ಖರೀದಿ ಮತ್ತು ತರಬೇತಿಯಲ್ಲಿ ಸಹಾಯ ಮಾಡಬಹುದು — ಸಮಸ್ಯೆ ಗಂಭೀರವಾಗುವ ಮೊದಲೇ ಸಂಪರ್ಕಿಸಿ.",
  "tips.storySells": "ಕಥೆಯುಳ್ಳ ವಸ್ತುಗಳಿಗೆ ಖರೀದಿದಾರರು ಹೆಚ್ಚು ಪಾವತಿಸುತ್ತಾರೆ. ನಿಮ್ಮ ತಂತ್ರ ಅಥವಾ ಕಲೆಯ ಇತಿಹಾಸದ ಬಗ್ಗೆ ಒಂದು ಸಣ್ಣ ಟಿಪ್ಪಣಿಯನ್ನು ನಿಮ್ಮ ಪಟ್ಟಿಗೆ ಸೇರಿಸಿ.",
  "badges.empty": "ಇನ್ನೂ ಯಾವುದೇ ಬ್ಯಾಡ್ಜ್‌ಗಳಿಲ್ಲ. ಬ್ಯಾಡ್ಜ್ ಗಳಿಸಲು ನಿಮ್ಮ ಮೊದಲ ಉತ್ಪನ್ನವನ್ನು ಪಟ್ಟಿ ಮಾಡಿ.",
