  "privacy.title": "ಗೌಪ್ಯತೆ ನೀತಿ",
  "privacy.lastUpdated": "ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ: ಸೆಪ್ಟೆಂಬರ್ 2026 • ಭಾರತ ಸರ್ಕಾರ ರಾಷ್ಟ್ರೀಯ ಡಿಜಿಟಲ್ ಮೂಲಸೌಕರ್ಯ",
