  "privacy.section3.intro": "ಸಂಗ್ರಹಿಸಿದ ಡೇಟಾವನ್ನು ಈ ಕೆಳಗಿನ ಸ್ಪಷ್ಟ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಮಾತ್ರ ಸಂಸ್ಕರಿಸಲಾಗುತ್ತದೆ:",
