  "privacy.section3.bullet2": "ಮಿಂಟಿಂಗ್ ಟ್ಯಾಂಪರ್-ಪ್ರೂಫ್ ಕ್ರಿಪ್ಟೋಗ್ರಾಫಿಕ್ Ed25519 ಡಿಜಿಟಲ್ ಮೂಲ ಪ್ರಮಾಣಪತ್ರಗಳು.",
  "privacy.section3.bullet4": "SMS ಮತ್ತು ಇಮೇಲ್ ಮೂಲಕ ಪೂರೈಸುವಿಕೆ ಮತ್ತು ವಿತರಣಾ ಸ್ಥಿತಿಯ ಅಧಿಸೂಚನೆಗಳನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳುವುದು.",
  "privacy.section4.heading": "4. ಮೂರನೇ ವ್ಯಕ್ತಿಯ ಡೇಟಾ ಮಾರಾಟದ ಮೇಲೆ ಸಂಪೂರ್ಣ ನಿಷೇಧ",
  "privacy.section5.heading": "5. ಕ್ರಿಪ್ಟೋಗ್ರಾಫಿಕ್ ಭದ್ರತೆ ಮತ್ತು ಕುಕಿ ನೀತಿ",
