  "terms.title": "ಸೇವಾ ನಿಯಮಗಳು",
  "terms.lastUpdated": "ಕೊನೆಯದಾಗಿ ನವೀಕರಿಸಲಾಗಿದೆ: ಸೆಪ್ಟೆಂಬರ್ 2026 • ಸಾಮಾಜಿಕ ನ್ಯಾಯ ಮತ್ತು ಸಬಲೀಕರಣ ಸಚಿವಾಲಯ, ಭಾರತ ಸರ್ಕಾರ",
  "terms.section1.heading": "1. ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಆದೇಶ ಮತ್ತು ಸಾರ್ವಜನಿಕ ಮೂಲಸೌಕರ್ಯ",
  "terms.section2.heading": "2. ಭೌಗೋಳಿಕ ಸೂಚನೆಗಳು (GI) ಮತ್ತು ದೃಢೀಕರಣ ಗುಣಮಟ್ಟ",
