  "trends.filter.empty": "ಈ ಫಿಲ್ಟರ್‌ಗಾಗಿ ಯಾವುದೇ ಪ್ರವೃತ್ತಿಗಳು ಕಂಡುಬಂದಿಲ್ಲ.",
  "trends.filter.viewAll": "ಎಲ್ಲಾ ಪ್ರವೃತ್ತಿಗಳನ್ನು ವೀಕ್ಷಿಸಿ",
  "trends.clusterPriority": "ಕ್ಲಸ್ಟರ್ ಆದ್ಯತೆ",
  "trends.readAloud": "ವಿವರಗಳನ್ನು ಆಲಿಸಿ",
  "trends.role.ministryAdvisor": "ಸಚಿವಾಲಯ ಕ್ಲಸ್ಟರ್ ಸಲಹೆಗಾರ",
  "trends.role.artisanContributor": "ಕುಶಲಕರ್ಮಿ ಕೊಡುಗೆದಾರ",
  "trends.role.communityMember": "ಸಮುದಾಯ ಸದಸ್ಯ",
  "trends.craftSimilar": "ಇದೇ ರೀತಿಯ ಕರಕುಶಲ ತಯಾರಿಸಿ",
  "trends.viewSocialPost": "ಪೋಸ್ಟ್ ವೀಕ್ಷಿಸಿ",
  "trends.sourceLabel": "ಮೂಲ: {domain}",
  "trends.item1.title": "ಯುರೋಪಿಯನ್ ಸಮ್ಮರ್ ಕಲೆಕ್ಷನ್‌ನಲ್ಲಿ ಅಜ್ರಖ್ ಮತ್ತು ಅರ್ಥ್ ಟೋನ್ಸ್",
  "trends.item1.desc": "ನೈಸರ್ಗಿಕ ಬಣ್ಣಗಳು ಮತ್ತು ಬೊಟಿಕ್ ಬೇಡಿಕೆಯಲ್ಲಿ ಹೆಚ್ಚುತ್ತಿರುವ ಆಧುನಿಕ ಉಡುಪುಗಳು.",
  "trends.item1.curator": "ಮೀರಾ ರಾವ್ (ಸಚಿವಾಲಯ ಸೋರ್ಸಿಂಗ್ ಸಲಹೆಗಾರರು)",
  "trends.item2.title": "ಖಾದಿ ಹಬ್ಬದ ಉಡುಪಿನಲ್ಲಿ ಸಮಕಾಲೀನ ಜರ್ದೋಜಿ ಬಾರ್ಡರ್",
  "trends.item2.desc": "ದೇಶೀಯ ಬೊಟಿಕ್‌ಗಳಲ್ಲಿ ಖಾದಿ ಉಡುಪುಗಳ ಮೇಲೆ ಜರ್ದೋಜಿ ಬಾರ್ಡರ್ ಜನಪ್ರಿಯತೆ.",
  "trends.item2.curator": "ರಾಜೇಶ್ ಸಿಂಘಾನಿಯಾ (ಮಾಸ್ಟರ್ ನೇಕಾರ, ವಾರಣಾಸಿ)",
  "trends.item3.title": "ಮಧುಬನಿ ಟೇಬಲ್ ಲಿನೆನ್ ಮತ್ತು ಸಿರಾಮಿಕ್ ಅಲಂಕಾರಗಳು",
  "trends.item3.desc": "ಸಾಂಪ್ರದಾಯಿಕ ಮಿಥಿಲಾ ನೈಸರ್ಗಿಕ ವರ್ಣದ್ರವ್ಯಗಳನ್ನು ಬಳಸಿದ ಡೈನಿಂಗ್ ಲಿನೆನ್.",
  "trends.item3.curator": "ಸೀತಾ ದೇವಿ (ಜಾನಪದ ಕಲಾವಿದೆ, ಮಧುಬನಿ)",
  "trends.item4.title": "ಕಾರ್ಪೊರೇಟ್ ಹ್ಯಾಂಡ್‌ಲೂಮ್ ಶುಕ್ರವಾರಕ್ಕೆ ತಿಳಿ ಚಂದೇರಿ ಸೀರೆಗಳು",
