  "pdp.qa.a": "ಉ:",
  "pdp.qa.by": "— {name}, ಕುಶಲಕರ್ಮಿ",
  "pdp.qa.askLabel": "ಕುಶಲಕರ್ಮಿಗೆ ಪ್ರಶ್ನೆ ಕೇಳಿ",
  "pdp.qa.askPlaceholder": "ಪ್ರಶ್ನೆ ಇದೆಯೇ? ಕುಶಲಕರ್ಮಿಗೆ ಕೇಳಿ",
  "pdp.qa.ask": "ಕೇಳಿ",
  "pdp.qa.sent": "ಪ್ರಶ್ನೆಯನ್ನು {artisan}ಗೆ ಕಳುಹಿಸಲಾಗಿದೆ. 24 ಗಂಟೆಗಳಲ್ಲಿ ಉತ್ತರ ಸಿಗುತ್ತದೆ.",
  "pdp.alsoViewed.heading": "ಇದನ್ನು ನೋಡಿದ ಗ್ರಾಹಕರು ಇವುಗಳನ್ನೂ ನೋಡಿದ್ದಾರೆ",
  "pdp.bullet.authentic": "{origin}ನಲ್ಲಿ ಸಂಪೂರ್ಣವಾಗಿ ಕೈಯಿಂದ ಮಾಡಿದ ನಿಜವಾದ {craft} ಕೃತಿ.",
  "pdp.bullet.gi": "ಭೌಗೋಳಿಕ ಸೂಚಕ ಪ್ರಮಾಣೀಕೃತ ({giNo}) — ಸಂರಕ್ಷಿತ ಮೂಲ, ಯಂತ್ರ ನಿರ್ಮಿತ ನಕಲಿ ಅಲ್ಲ.",
  "pdp.bullet.cluster": "ಪಟ್ಟಿ ಮಾಡುವ ಮೊದಲು ಕರಕುಶಲ ಕ್ಲಸ್ಟರ್ ಸಾಂಪ್ರದಾಯಿಕ ತಂತ್ರವನ್ನು ಪರಿಶೀಲಿಸಿದೆ.",
  "pdp.bullet.material": "ವಸ್ತು: {material}. ಬಣ್ಣ ಮತ್ತು ವಿನ್ಯಾಸದಲ್ಲಿ ಸಣ್ಣ ವ್ಯತ್ಯಾಸಗಳು ಕೈಕೆಲಸದ ಗುರುತು, ದೋಷವಲ್ಲ.",
  "pdp.bullet.mto": "ಆರ್ಡರ್ ಮೇಲೆ ತಯಾರಿಕೆ: ನಿಮ್ಮ ಆರ್ಡರ್ ಬಂದ ಮೇಲೆ ಕೆಲಸ ಶುರುವಾಗುತ್ತದೆ, ಆದ್ದರಿಂದ ವಿನಂತಿಯ ಮೇಲೆ ಬದಲಾವಣೆ ಸಾಧ್ಯ.",
  "pdp.bullet.ready": "ಸಿದ್ಧ ಸ್ಟಾಕ್: ಕುಶಲಕರ್ಮಿ 2 ಕೆಲಸದ ದಿನಗಳಲ್ಲಿ ಪ್ಯಾಕ್ ಮಾಡಿ ಕಳುಹಿಸುತ್ತಾರೆ.",
  "pdp.bullet.direct": "ಹಣ ನೇರವಾಗಿ {artisan} ಅವರ ಬ್ಯಾಂಕ್ ಖಾತೆಗೆ ಹೋಗುತ್ತದೆ — ಯಾವುದೇ ಮಧ್ಯವರ್ತಿ ಇಲ್ಲ.",
  "pdp.bullet.sealed": "ಪರಿಶೀಲಿತ ತಂತ್ರವನ್ನು ದಾಖಲಿಸುವ, ತಿದ್ದುಪಡಿ-ನಿರೋಧಕ ಮೂಲಾಧಾರ ಮುದ್ರೆಯೊಂದಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ.",
