  "pdp.material.pashmina": "ಕೈಯಿಂದ ನೂಲಿದ ಪಶ್ಮಿನಾ ಉಣ್ಣೆ",
  "pdp.material.silk": "ಜರಿಯೊಂದಿಗೆ ಶುದ್ಧ ಮಲ್ಬೆರಿ ರೇಷ್ಮೆ",
  "pdp.material.carpet": "ಹತ್ತಿ ನೂಲಿನ ಮೇಲೆ ಕೈಯಿಂದ ಗಂಟು ಹಾಕಿದ ಉಣ್ಣೆ",
  "pdp.material.cotton": "ಕೈಮಗ್ಗದ ಹತ್ತಿ",
  "pdp.material.dyed": "ನೈಸರ್ಗಿಕ ಸಸ್ಯ ಬಣ್ಣಗಳಿಂದ ಬಣ್ಣ ಹಾಕಿದ ಹತ್ತಿ",
  "pdp.material.embroidery": "ಕೈ ಕಸೂತಿ ಮಾಡಿದ ಬಟ್ಟೆ",
  "pdp.material.clay": "ಕೈಯಿಂದ ರೂಪಿಸಿ, ಕುಲುಮೆಯಲ್ಲಿ ಸುಟ್ಟ ಮಣ್ಣು",
  "pdp.material.brass": "ಹಿತ್ತಾಳೆ ಅಥವಾ ಕಂಚಿನ ಮಿಶ್ರಲೋಹ",
