  "pdp.material.fibre": "ನೈಸರ್ಗಿಕ ಬಿದಿರು, ಬೆತ್ತ ಮತ್ತು ಹುಲ್ಲಿನ ನಾರು",
  "pdp.material.stone": "ಕೈಯಿಂದ ಕೆತ್ತಿದ ನೈಸರ್ಗಿಕ ಕಲ್ಲು",
  "pdp.material.paper": "ನೈಸರ್ಗಿಕ ಬಣ್ಣಗಳೊಂದಿಗೆ ಕೈಯಿಂದ ಮಾಡಿದ ಕಾಗದ",
  "pdp.material.silver": "ಸ್ಟರ್ಲಿಂಗ್ ಬೆಳ್ಳಿ",
  "pdp.material.default": "ನೈಸರ್ಗಿಕ, ಸ್ಥಳೀಯ ವಸ್ತುಗಳು",
  "pdp.care.dryClean": "ಡ್ರೈ ಕ್ಲೀನ್ ಮಾತ್ರ. ಮಸ್ಲಿನ್‌ನಲ್ಲಿ ಮಡಚಿ, ನೇರ ಸೂರ್ಯನ ಬೆಳಕಿನಿಂದ ದೂರ ಇಡಿ.",
  "pdp.care.handWash": "ತಣ್ಣೀರಿನಲ್ಲಿ ಮೃದುವಾದ ಸೋಪ್‌ನೊಂದಿಗೆ ನಿಧಾನವಾಗಿ ಕೈಯಿಂದ ತೊಳೆಯಿರಿ. ನೆರಳಿನಲ್ಲಿ ಒಣಗಿಸಿ.",
  "pdp.care.wipe": "ಮೃದುವಾದ ಒಣ ಬಟ್ಟೆಯಿಂದ ಒರೆಸಿ. ಎಚ್ಚರಿಕೆಯಿಂದ ನಿರ್ವಹಿಸಿ; ಡಿಶ್‌ವಾಶರ್‌ನಲ್ಲಿ ಇಡಬೇಡಿ.",
  "pdp.care.polish": "ಸಾಂದರ್ಭಿಕವಾಗಿ ಒಣ ಬಟ್ಟೆಯಿಂದ ಹೊಳಪು ಮಾಡಿ. ನೀರು ಮತ್ತು ಆಮ್ಲೀಯ ಕ್ಲೀನರ್‌ಗಳನ್ನು ತಪ್ಪಿಸಿ.",
  "pdp.care.dry": "ತೇವಾಂಶದಿಂದ ದೂರ ಇಡಿ. ಮೃದುವಾದ ಬ್ರಷ್‌ನಿಂದ ಧೂಳು ತೆಗೆಯಿರಿ.",
  "pdp.care.frame": "ಗಾಜಿನ ಹಿಂದೆ ಫ್ರೇಮ್ ಮಾಡಿ. ತೇವಭರಿತ ಗೋಡೆಗಳು ಮತ್ತು ನೇರ ಸೂರ್ಯನ ಬೆಳಕಿನಿಂದ ದೂರ ಇಡಿ.",
  "pdp.care.default": "ಎಚ್ಚರಿಕೆಯಿಂದ ನಿರ್ವಹಿಸಿ. ಮೃದುವಾದ ಒಣ ಬಟ್ಟೆಯಿಂದ ನಿಧಾನವಾಗಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ.",
  "pdp.review.1.title": "ಫೋಟೋಗಳಿಗಿಂತಲೂ ಸುಂದರ",
  "pdp.review.1.body": "{craft} ಕೆಲಸ ಪ್ರತ್ಯಕ್ಷವಾಗಿ ಇನ್ನೂ ಸೂಕ್ಷ್ಮವಾಗಿದೆ. ಸಣ್ಣ ಅಸಮಾನತೆಗಳೇ ಇದು ಕೈಯಿಂದ ಮಾಡಿದ್ದು ಎಂದು ತೋರಿಸುತ್ತವೆ. ತುಂಬಾ ಎಚ್ಚರಿಕೆಯಿಂದ ಪ್ಯಾಕ್ ಮಾಡಲಾಗಿತ್ತು.",
  "pdp.review.2.title": "ಪ್ರತಿ ರೂಪಾಯಿಗೂ ಯೋಗ್ಯ",
  "pdp.review.2.body": "ಹಣ ನೇರವಾಗಿ {artisan}ಗೆ ಹೋಗುತ್ತದೆ ಎಂದು ತಿಳಿದು ನಿರ್ಧಾರ ಸುಲಭವಾಯಿತು. ವಸ್ತುಸಂಗ್ರಹಾಲಯ ಮಟ್ಟದ ಗುಣಮಟ್ಟ.",
  "pdp.review.3.title": "ಸುಂದರ, ಸ್ವಲ್ಪ ತಡವಾಗಿ ಬಂತು",
  "pdp.review.3.body": "ಅಂದಾಜಿಗಿಂತ ಮೂರು ದಿನ ತಡವಾಗಿ ಬಂತು, ಆದರೆ ಕುಶಲಕರ್ಮಿ ಸಂದೇಶ ಕಳುಹಿಸಿ ಕಾರಣ ತಿಳಿಸಿದರು. ವಸ್ತು ಸ್ವತಃ ಅದ್ಭುತವಾಗಿದೆ.",
  "pdp.review.4.title": "ಮುದ್ರೆ ಪರಿಶೀಲಿಸಿದೆ, ಎಲ್ಲಾ ನಿಜ",
  "pdp.review.4.body": "ಬಂದ ಕೂಡಲೇ ಮೂಲಾಧಾರ ದಾಖಲೆಯನ್ನು ಪರಿಶೀಲಿಸಿದೆ, ಅದು ಪಟ್ಟಿಗೆ ಸಂಪೂರ್ಣ ಹೊಂದಿಕೆಯಾಯಿತು. ಕೊನೆಗೂ ಆನ್‌ಲೈನ್ ಕರಕುಶಲ ಖರೀದಿಯಲ್ಲಿ ನಂಬಿಕೆ.",
  "pdp.review.5.title": "ಚೆನ್ನಾಗಿದೆ, ಆದರೆ ಅಳತೆ ನೋಡಿಕೊಳ್ಳಿ",
  "pdp.review.5.body": "ಉತ್ತಮ ಕರಕುಶಲತೆ, ಆದರೆ ನಿರೀಕ್ಷೆಗಿಂತ ಚಿಕ್ಕದಾಗಿದೆ. ಆರ್ಡರ್ ಮಾಡುವ ಮೊದಲು ವಿವರ ಪಟ್ಟಿಯಲ್ಲಿ ಅಳತೆಗಳನ್ನು ಓದಿಕೊಳ್ಳಿ.",
  "pdp.qa.1.q": "ಇದು ಕೈಯಿಂದ ಮಾಡಿದ್ದೋ ಅಥವಾ ಯಂತ್ರದಿಂದ?",
  "pdp.qa.1.a": "ಸಂಪೂರ್ಣವಾಗಿ ಕೈಯಿಂದ ಮಾಡಿದ್ದು. ಜಿಐ ಟ್ಯಾಗ್ ಮತ್ತು ಮೂಲಾಧಾರ ಮುದ್ರೆ ಎರಡೂ ತಂತ್ರವನ್ನು ಖಚಿತಪಡಿಸುತ್ತವೆ.",
  "pdp.qa.2.q": "ನಾನು ಬೇರೆ ಬಣ್ಣ ಕೇಳಬಹುದೇ?",
  "pdp.qa.2.aMto": "ಹೌದು, ಆರ್ಡರ್ ಮೇಲೆ ತಯಾರಾಗುವ ವಸ್ತುಗಳಲ್ಲಿ ಬದಲಾವಣೆ ಮಾಡಬಹುದು — ಆರ್ಡರ್ ಟಿಪ್ಪಣಿಯಲ್ಲಿ ಬರೆಯಿರಿ.",
  "pdp.qa.2.aReady": "ಇದು ಸಿದ್ಧ ಸ್ಟಾಕ್ ವಸ್ತು, ಆದ್ದರಿಂದ ಬಣ್ಣಗಳು ತೋರಿಸಿದಂತೆಯೇ ಇರುತ್ತವೆ. ವಿಶೇಷ ಆರ್ಡರ್‌ಗಾಗಿ ಕುಶಲಕರ್ಮಿಗೆ ಸಂದೇಶ ಕಳುಹಿಸಿ.",
  "pdp.qa.3.q": "ಕಳುಹಿಸಲು ಇದನ್ನು ಹೇಗೆ ಪ್ಯಾಕ್ ಮಾಡಲಾಗುತ್ತದೆ?",
  "pdp.qa.3.a": "ಬಟ್ಟೆಯಲ್ಲಿ, ನಂತರ ಬಬಲ್ ರಾಪ್‌ನಲ್ಲಿ ಸುತ್ತಿ, ಎರಡು ಗೋಡೆಗಳ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ. ದುರ್ಬಲ ವಸ್ತುಗಳಿಗೆ ವಿಶೇಷ ಕ್ರೇಟ್.",
  "pdp.qa.4.q": "ತೊಳೆದ ನಂತರ ಬಣ್ಣ ಮಾಸುತ್ತದೆಯೇ?",
  "pdp.qa.4.a": "ನೈಸರ್ಗಿಕ ಬಣ್ಣಗಳು ವರ್ಷಗಳ ಕಳೆದಂತೆ ಸ್ವಲ್ಪ ಮಂದವಾಗುತ್ತವೆ, ಇದು ಸಹಜ. ಬಣ್ಣ ಉಳಿಸಿಕೊಳ್ಳಲು ಆರೈಕೆ ಸೂಚನೆಗಳನ್ನು ಅನುಸರಿಸಿ.",
  "pdp.storefront.bio": "{name} {district}ನಲ್ಲಿ {craft} ಕರಕುಶಲ ಕೆಲಸ ಮಾಡುತ್ತಾರೆ ಮತ್ತು ಖರೀದಿದಾರರಿಗೆ ನೇರವಾಗಿ ಮಾರಾಟ ಮಾಡುತ್ತಾರೆ.",
  "income.baseline.step": "ಹಿಂದಿನ ಆದಾಯ",
  "income.baseline.question": "ಕಲಾಕೃತಿಗೆ ಮೊದಲು, ನಿಮ್ಮ ಕರಕುಶಲದಿಂದ ತಿಂಗಳಿಗೆ ಎಷ್ಟು ಸಂಪಾದಿಸುತ್ತಿದ್ದಿರಿ?",
  "income.baseline.why": "ಕಲಾಕೃತಿ ನಿಮ್ಮ ಆದಾಯಕ್ಕೆ ಎಷ್ಟು ಸೇರಿಸುತ್ತದೆ ಎಂಬುದನ್ನು ಇದು ತೋರಿಸುತ್ತದೆ. ನಿಮ್ಮ ಉತ್ತರವನ್ನು ನೀವು ಮಾತ್ರ ನೋಡಬಹುದು; ಸರ್ಕಾರ ಅನಾಮಧೇಯ ಒಟ್ಟು ಸಂಖ್ಯೆಗಳನ್ನು ಮಾತ್ರ ನೋಡುತ್ತದೆ.",
