  "income.card.selfReported": "ಕಲಾಕೃತಿಗೆ ಮೊದಲಿನ ನಿಮ್ಮ ಆದಾಯವನ್ನು ನೀವೇ ತಿಳಿಸಿದ್ದೀರಿ.",
  "income.card.noBaseline": "ನಿಮ್ಮ ಬೆಳವಣಿಗೆಯನ್ನು ನೋಡಲು ಕಲಾಕೃತಿಗೆ ಮೊದಲು ಎಷ್ಟು ಸಂಪಾದಿಸಿದ್ದೀರಿ ಎಂದು ತಿಳಿಸಿ.",
