  "impact.refreshedAt": "{time} ರಂತೆ ಡೇಟಾ",
  "impact.suppressedNote": "ಈ ಫಿಲ್ಟರ್‌ಗಳೊಂದಿಗೆ 5 ಕ್ಕಿಂತ ಕಡಿಮೆ ಕುಶಲಕರ್ಮಿಗಳು ಹೊಂದಿಕೆಯಾಗುತ್ತಾರೆ, ಆದ್ದರಿಂದ ಸಂಖ್ಯೆಗಳನ್ನು ಮರೆಮಾಡಲಾಗಿದೆ.",
  "impact.selfReported": "ಕಲಾಕೃತಿಗೆ ಮೊದಲಿನ ಆದಾಯ ಕುಶಲಕರ್ಮಿಗಳಿಂದ ಸ್ವಯಂ ವರದಿ ಮಾಡಲಾಗಿದೆ. ಕನಿಷ್ಠ 90 ದಿನ ವೇದಿಕೆಯಲ್ಲಿ ಇದ್ದ ಕುಶಲಕರ್ಮಿಗಳಿಗೆ ಮಾತ್ರ ಬೆಳವಣಿಗೆಯನ್ನು ತೋರಿಸಲಾಗುತ್ತದೆ.",
