  "caseStudies.dhamadka-ajrakh.rows.4.dimension": "ಪಾವತಿ ಇತ್ಯರ್ಥ",
  "caseStudies.dhamadka-ajrakh.rows.4.before": "ಕ್ರೆಡಿಟ್ ರವಾನೆಯ ಮೇಲೆ 6 ರಿಂದ 9 ತಿಂಗಳ ವಿಳಂಬ ಪಾವತಿ",
  "caseStudies.dhamadka-ajrakh.rows.4.after": "ವಾಹಕ ಸ್ಕ್ಯಾನ್‌ನಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತ 48-ಗಂಟೆಗಳ ಎಸ್ಕ್ರೊ ಪಾವತಿ",
  "caseStudies.dhamadka-ajrakh.problem": "ದಶಕಗಳಿಂದ, ವಾಣಿಜ್ಯ ಫಾಸ್ಟ್-ಫ್ಯಾಶನ್ ಮನೆಗಳಿಂದ ಆಮದು ಮಾಡಿಕೊಳ್ಳುವ ಸಂಶ್ಲೇಷಿತ ರಾಸಾಯನಿಕ ಬ್ಲಾಕ್-ಪ್ರಿಂಟ್‌ಗಳು ಧಮಡ್ಕಾದಲ್ಲಿ ಅಧಿಕೃತ ಹ್ಯಾಂಡ್ ಬ್ಲಾಕ್-ಪ್ರಿಂಟರ್‌ಗಳನ್ನು ತೀವ್ರವಾಗಿ ದುರ್ಬಲಗೊಳಿಸಿದವು. ರಾಸಾಯನಿಕ ಬದಲಿಗಳು 20% ಬೆಲೆಯಲ್ಲಿ ಮಾರುಕಟ್ಟೆಗಳನ್ನು ತುಂಬಿದವು, ಸಾಂಪ್ರದಾಯಿಕ ಮಾಸ್ಟರ್‌ಗಳು ಪ್ರಾಚೀನ 16-ಹಂತದ ಸಸ್ಯಶಾಸ್ತ್ರೀಯ ಪ್ರತಿರೋಧ ತಂತ್ರಗಳನ್ನು ದುರ್ಬಲಗೊಳಿಸುವಂತೆ ಒತ್ತಾಯಿಸಿದರು.",
  "caseStudies.dhamadka-ajrakh.intervention": "ಕಲಾಕೃತಿ ಮೂಲಕ, ಧಮಡ್ಕ ಗಿಲ್ಡ್ ನೈಜ ಇಂಡಿಗೋಫೆರಾ ಟಿಂಕ್ಟೋರಿಯಾ ವ್ಯಾಟ್ ಹುದುಗುವಿಕೆ ಮತ್ತು ಅಕೇಶಿಯಾ ಅರೇಬಿಕಾ ಗಮ್ ರೆಸಿಸ್ಟ್‌ಗಳ ಸ್ಪೆಕ್ಟ್ರೋಸ್ಕೋಪಿಕ್ ಪರಿಶೀಲನೆಯನ್ನು ಜಾರಿಗೆ ತಂದಿತು. ಪ್ರತಿ ಸ್ಟೋಲ್ ಮತ್ತು ಅಂಗಳದ ಉದ್ದವು ಕ್ಲಸ್ಟರ್‌ನಿಂದ ಹೊರಡುವ ಮೊದಲು ಬದಲಾಗದ Ed25519 ಕ್ರಿಪ್ಟೋಗ್ರಾಫಿಕ್ ಸೀಲ್ ಮತ್ತು NFC QR ಟ್ಯಾಗ್ ಅನ್ನು ಪಡೆಯುತ್ತದೆ.",
  "caseStudies.dhamadka-ajrakh.impact": "ದೃಢೀಕರಣ ಪರಿಶೀಲನೆಯು ಗಿಲ್ಡ್ ಅನ್ನು ನೇರವಾಗಿ ಐಷಾರಾಮಿ ವಿನ್ಯಾಸದ ಮನೆಗಳು ಮತ್ತು ವಿದೇಶಿ ಸಾಂಸ್ಕೃತಿಕ ಕಾರ್ಯಾಚರಣೆಗಳಿಗೆ ಮಾರಾಟ ಮಾಡಲು ಅವಕಾಶ ಮಾಡಿಕೊಟ್ಟಿತು. ಮನೆಯ ಆದಾಯವು 3.37x ಏರಿಕೆಯಾಗಿದೆ, ಇದು ಸಾಮೂಹಿಕ ನೈಸರ್ಗಿಕ ಡೈ ಸೀಡ್ ಬ್ಯಾಂಕ್ ಮತ್ತು 14 ಯುವ ಪ್ರಿಂಟರ್‌ಗಳಿಗೆ ಅಪ್ರೆಂಟಿಸ್‌ಶಿಪ್ ನಿಧಿಯನ್ನು ರಚಿಸಲು ಅನುವು ಮಾಡಿಕೊಡುತ್ತದೆ.",
  "caseStudies.dhamadka-ajrakh.quote.text": "ಖರೀದಿದಾರರು ನಮ್ಮ ಬಟ್ಟೆಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿದಾಗ ಮತ್ತು ಇಂಡಿಗೊ ವ್ಯಾಟ್‌ನಲ್ಲಿ ನಮ್ಮ ಕೈಗಳನ್ನು ನೋಡಿದಾಗ, 16 ಹಂತಗಳನ್ನು ಏಕೆ ಯದ್ವಾತದ್ವಾ ಮಾಡಲಾಗುವುದಿಲ್ಲ ಎಂದು ಅವರು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುತ್ತಾರೆ. ಕಲಾಕೃತಿ ನಮ್ಮ ಗೌರವವನ್ನು ಮರಳಿ ನೀಡಿದರು.",
  "caseStudies.dhamadka-ajrakh.quote.author": "ಇಸ್ಮಾಯಿಲ್ ಮೊಹಮ್ಮದ್ ಖತ್ರಿ",
  "caseStudies.dhamadka-ajrakh.quote.role": "ಮಾಸ್ಟರ್ ಕ್ರಾಫ್ಟ್ಸ್‌ಮ್ಯಾನ್ ಮತ್ತು ರಾಷ್ಟ್ರೀಯ ಪ್ರಶಸ್ತಿ ಪುರಸ್ಕೃತ, ಧಮಡ್ಕ",
  "caseStudies.varanasi-kadwa.title": "ವಾರಣಾಸಿ ಕಡ್ವಾ ಪಿಟ್-ಲೂಮ್ ಪುನರುಜ್ಜೀವನ",
  "caseStudies.varanasi-kadwa.subtitle": "ಪರಭಕ್ಷಕ 38% ಬ್ರೋಕರ್ ಶುಲ್ಕವನ್ನು ತೆಗೆದುಹಾಕುವುದು ಮತ್ತು ಪರಂಪರೆಯ ರೇಷ್ಮೆ ನೇಕಾರರಿಗೆ ನೇರ DBT ಪಾವತಿಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತಗೊಳಿಸುವುದು.",
  "caseStudies.varanasi-kadwa.cluster": "ವಾರಣಾಸಿ ಸಿಲ್ಕ್ ವೀವರ್ ಫೆಸಿಲಿಟಿ ಸೆಂಟರ್",
