  "caseStudies.varanasi-kadwa.rows.1.after": "86 ಪಿಟ್-ಲೂಮ್‌ಗಳನ್ನು 10 ತಿಂಗಳ ಮುಂಚಿತವಾಗಿ ಜಿಇಎಂ ಲಾಟ್‌ಗಳ ಮೂಲಕ ಬುಕ್ ಮಾಡಲಾಗಿದೆ",
