  "caseStudies.varanasi-kadwa.rows.3.before": "ಸರ್ಕಾರಿ ಶೃಂಗಸಭೆಗಳು ಅಥವಾ ಕಾರ್ಪೊರೇಟ್ ಉಡುಗೊರೆಗಳಿಗೆ ಶೂನ್ಯ ಪ್ರವೇಶ",
  "caseStudies.varanasi-kadwa.rows.3.after": "ರಾಜ್ಯ ನಿಯೋಗಗಳು ಮತ್ತು ಹೋಟೆಲ್ ಸರಪಳಿಗಳಿಂದ ನೇರ ಸಂಗ್ರಹಣೆ",
  "caseStudies.varanasi-kadwa.problem": "ವಾರಣಾಸಿಯಲ್ಲಿನ ಮಾಸ್ಟರ್ ಝರಿ ನೇಕಾರರು ಬಹು ಹಂತದ ಬಜಾರ್ ಮಧ್ಯವರ್ತಿಗಳ ಮೇಲೆ ಅವಲಂಬಿತರಾಗಿದ್ದರು, ಅವರು 35-40% ಚಿಲ್ಲರೆ ಮಾರ್ಜಿನ್‌ಗಳನ್ನು ಉಳಿಸಿಕೊಂಡರು ಮತ್ತು 9 ತಿಂಗಳವರೆಗೆ ಪಾವತಿಗಳನ್ನು ವಿಳಂಬಗೊಳಿಸಿದರು, ನೇಯ್ಗೆ ಮಾಡುವ ಕುಟುಂಬಗಳನ್ನು ಆವರ್ತಕ ಮಾನ್ಸೂನ್ ಋಣಭಾರಕ್ಕೆ ಒತ್ತಾಯಿಸಿದರು.",
  "caseStudies.varanasi-kadwa.intervention": "ಕಲಾಕೃತಿಯ ಸಾಂಸ್ಥಿಕ ಸಂಗ್ರಹಣೆ ಕೇಂದ್ರವು ರಾಜ್ಯ ಶೃಂಗಸಭೆಯ ಆತಿಥ್ಯ ಗುಂಪುಗಳು ಮತ್ತು ಕಾರ್ಪೊರೇಟ್ ಗಿಫ್ಟಿಂಗ್ ಕನ್ಸೋರ್ಷಿಯಾಗಳಿಗೆ ಸಾಮೂಹಿಕ ಬೃಹತ್ ಆದೇಶಗಳನ್ನು ನೇರವಾಗಿ ಪರಿವಾರ್ ಬಂಕರ್ SHG ಯೊಂದಿಗೆ ಇರಿಸಲು ಅವಕಾಶ ಮಾಡಿಕೊಟ್ಟಿತು. ಮಗ್ಗದ ಮೈಲಿಗಲ್ಲು ದೃಢೀಕರಣದ ಮೇಲೆ ನೇರ DBT ವರ್ಗಾವಣೆಗಳೊಂದಿಗೆ ಪಾವತಿ ಎಸ್ಕ್ರೊ ಸ್ವಯಂಚಾಲಿತವಾಗಿರುತ್ತದೆ.",
  "caseStudies.varanasi-kadwa.impact": "ರವಾನೆಯಾದ 48 ಗಂಟೆಗಳ ಒಳಗೆ ನೇಕಾರರಿಗೆ ಒಟ್ಟು ₹1.48 ಕೋಟಿ ವಿತರಣೆಯಾಗಿದೆ. 86 ಪಿಟ್-ಲೂಮ್‌ಗಳನ್ನು ಈಗ 12-ತಿಂಗಳ ಮುಂಗಡ ಸೈಕಲ್‌ಗಳಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ಕಾಯ್ದಿರಿಸಲಾಗಿದೆ, ಕಾಲೋಚಿತ ಬಡತನವನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ನಿವಾರಿಸುತ್ತದೆ.",
  "caseStudies.varanasi-kadwa.quote.text": "ಮೂರು ತಲೆಮಾರುಗಳವರೆಗೆ, ಅಂತಿಮ ಖರೀದಿದಾರನ ಮುಖವನ್ನು ನಾವು ಎಂದಿಗೂ ನೋಡಲಿಲ್ಲ. ಈಗ ನಾವು ಇಂಟರ್‌ಲಾಕ್ ಮಾಡುವ ಪ್ರತಿಯೊಂದು ಸೀರೆಯೊಂದಿಗೆ ನಮ್ಮ ಹೆಸರು ಮತ್ತು ಮಗ್ಗದ ನಿರ್ದೇಶಾಂಕಗಳು ಪ್ರಯಾಣಿಸುತ್ತವೆ.",
  "caseStudies.varanasi-kadwa.quote.author": "ಈಶಾನ್",
  "caseStudies.varanasi-kadwa.quote.role": "ಲೀಡ್ ಪಿಟ್-ಲೂಮ್ ವೀವರ್, ವಾರಣಾಸಿ ಸಿಲ್ಕ್ ಗಿಲ್ಡ್",
  "caseStudies.bastar-lost-wax.title": "ಬಸ್ತಾರ್ ಲಾಸ್ಟ್-ವ್ಯಾಕ್ಸ್ ಮೆಟಲರ್ಜಿಯನ್ನು ಸಂರಕ್ಷಿಸುವುದು",
