  "caseStudies.bastar-lost-wax.rows.3.after": "100% ಪೆಹಚಾನ್ ಮತ್ತು ಪಿಎಂ ವಿಶ್ವಕರ್ಮ ಪರಿಶೀಲಿಸಿದ ಐಡಿ ಕಾರ್ಡ್‌ಗಳು",
  "caseStudies.bastar-lost-wax.problem": "ಬಾಷ್ಪಶೀಲ ತಾಮ್ರ ಮತ್ತು ಸತುವು ಸ್ಕ್ರ್ಯಾಪ್ ಬೆಲೆಯು ಬುಡಕಟ್ಟು ಧೋಕ್ರಾ ಶಿಲ್ಪಿಗಳಿಗೆ ಕಚ್ಚಾ ಜೇನುಮೇಣ, ಜೇಡಿಮಣ್ಣು ಮತ್ತು ಎರಕಹೊಯ್ದ ಲೋಹಗಳನ್ನು ಮುಂಗಡವಾಗಿ ಖರೀದಿಸಲು ಅಸಾಧ್ಯವಾಯಿತು, ಇದು ಮಾನವೀಯತೆಯ ಅತ್ಯಂತ ಹಳೆಯ ನಾನ್-ಫೆರಸ್ ಎರಕಹೊಯ್ದ ವಂಶಾವಳಿಯನ್ನು ಅಳಿಸಿಹಾಕುವ ಬೆದರಿಕೆ ಹಾಕಿತು.",
  "caseStudies.bastar-lost-wax.intervention": "ವೇದಿಕೆಯು ಸಾಂಸ್ಥಿಕ ಶೃಂಗಸಭೆಯ ಸಂಗ್ರಹಣೆ ಕಿಟ್‌ಗಳಿಂದ ಬೆಂಬಲಿತ ಕಚ್ಚಾ ವಸ್ತುಗಳ ದಾಸ್ತಾನು ಸಾಲಗಳನ್ನು ಪರಿಚಯಿಸಿತು. ಶಿಲ್ಪಿಗಳು ಕರಗಿದ ಸುರಿಯುವಿಕೆಯನ್ನು ತಮ್ಮ ಕುಶಲಕರ್ಮಿಗಳ ಅಪ್ಲಿಕೇಶನ್‌ನಲ್ಲಿ ದಾಖಲಿಸುತ್ತಾರೆ, ಕಲಬೆರಕೆಯಿಲ್ಲದ ಬೆಲ್ ಲೋಹದ ಮಿಶ್ರಲೋಹಗಳನ್ನು ಸಾಬೀತುಪಡಿಸುತ್ತಾರೆ.",
  "caseStudies.bastar-lost-wax.impact": "ಕೊಂಡಗಾಂವ್ ಕುಲುಮೆಗಳಿಗೆ 28 ​​ಹೊಸ ಬುಡಕಟ್ಟು ಅಪ್ರೆಂಟಿಸ್‌ಗಳು ಸೇರ್ಪಡೆಗೊಂಡಿದ್ದಾರೆ. ಬಸ್ತಾರ್ ಲಾಸ್ಟ್-ಮೇಣದ ಶಿಲ್ಪಗಳು ಈಗ ವಿಶ್ವಾದ್ಯಂತ ಪ್ರಮುಖ ಸಾಂಸ್ಥಿಕ ಲಾಬಿಗಳು ಮತ್ತು ರಾಜತಾಂತ್ರಿಕ ಉಡುಗೊರೆಗಳನ್ನು ಅಲಂಕರಿಸುತ್ತವೆ.",
  "caseStudies.bastar-lost-wax.quote.text": "ನಮ್ಮ ಪೂರ್ವಜರು ಸಾಲ್ ಕಾಡುಗಳಿಂದ ಜೇನುಮೇಣವನ್ನು ಬಳಸುತ್ತಿದ್ದರು. ಕಲಾಕೃತಿ ನಮ್ಮ ಕುಲುಮೆಗಳು ಮುಂದಿನ ಪೀಳಿಗೆಗೆ ಸಾಲದ ಭಯವಿಲ್ಲದೆ ಉರಿಯುವಂತೆ ಮಾಡುತ್ತದೆ.",
  "caseStudies.bastar-lost-wax.quote.author": "ಬುಧೇಶ್ವರ ಘಡ್ವಾ",
  "caseStudies.bastar-lost-wax.quote.role": "ಹಿರಿಯ ಸಿರ್-ಪರ್ಡ್ಯೂ ಮೆಟಲ್ ವರ್ಕರ್, ಕೊಂಡಗಾಂವ್",
  "fairs.data.surajkund-2026.title": "ಸೂರಜ್‌ಕುಂಡ್ ಅಂತರಾಷ್ಟ್ರೀಯ ಕರಕುಶಲ ಮೇಳ",
