  "fairs.data.surajkund-2026.description": "ವಿಶ್ವದ ಅತಿದೊಡ್ಡ ಬಯಲು ಕರಕುಶಲ ಮೇಳವು ಅಧಿಕೃತ ಗ್ರಾಮೀಣ ಕರಕುಶಲ ವಂಶಾವಳಿಗಳು, ಲಿವಿಂಗ್ ಪಿಟ್ ಲೂಮ್‌ಗಳು ಮತ್ತು ರಾಷ್ಟ್ರೀಯ ಪ್ರಶಸ್ತಿ ಪುರಸ್ಕೃತರಿಂದ ಲೈವ್ ವುಡ್‌ಕಾರ್ವಿಂಗ್ ಪ್ರದರ್ಶನಗಳನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ.",
  "fairs.data.surajkund-2026.partnerMinistry": "ಪ್ರವಾಸೋದ್ಯಮ ಸಚಿವಾಲಯ ಮತ್ತು ಹರಿಯಾಣ ಪ್ರವಾಸೋದ್ಯಮ ಮಂಡಳಿ",
